import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyPhuongTien = () => {
    // 1. TỐI ƯU BACKEND: Giả lập dữ liệu từ Database
    const [vehiclesData, setVehiclesData] = useState({
        "101": [
            { id: 1, type: "Xe máy", plate: "43A-123.45" },
            { id: 2, type: "Ô tô", plate: "43B-999.99" }
        ],
        "102": [
            { id: 3, type: "Xe máy", plate: "43C-456.78" }
        ],
        "201": [], // Phòng chưa đăng ký xe
        // Các số phòng khác sẽ được load từ API sau này
    });

    const [selectedRoom, setSelectedRoom] = useState(null);

    // Tạo danh sách số phòng để hiển thị bên trái (như ảnh 2)
    const rooms = [
        "101", "102", "103", "104", "105",
        "201", "202", "203", "204", "205",
        "301", "302", "303", "304", "305",
        "401", "402", "403", "404", "405",
        "501", "502", "503", "504", "505"
    ];

    return (
        <div style={containerStyle} className="glass-card">
            <h2 style={headerTitleStyle}>🚗 QUẢN LÝ PHƯƠNG TIỆN</h2>

            <div style={contentWrapperStyle}>
                {/* KHUNG TRÁI: CHỌN SỐ PHÒNG (Giống ảnh 2) */}
                <div className="custom-scrollbar" style={leftSidebarStyle}>
                    <div style={roomGridStyle}>
                        {rooms.map(room => (
                            <button 
                                key={room}
                                onClick={() => setSelectedRoom(room)}
                                style={{
                                    ...roomButtonStyle,
                                    backgroundColor: selectedRoom === room ? '#8b5e5e' : '#fbc02d',
                                    color: selectedRoom === room ? '#fff' : '#333',
                                    transform: selectedRoom === room ? 'scale(1.05)' : 'scale(1)'
                                }}
                            >
                                {room}
                            </button>
                        ))}
                    </div>
                </div>

                {/* KHUNG PHẢI: HIỂN THỊ THÔNG TIN XE */}
                <div style={rightContentStyle}>
                    {selectedRoom ? (
                        <div style={infoCardStyle}>
                            <h1 style={roomHeaderStyle}>PHÒNG {selectedRoom}</h1>
                            <div style={dividerStyle}></div>

                            <h3 style={{ color: '#555', marginBottom: '15px' }}>Danh sách phương tiện đăng ký:</h3>

                            <div className="custom-scrollbar" style={vehicleListContainer}>
                                {vehiclesData[selectedRoom] && vehiclesData[selectedRoom].length > 0 ? (
                                    vehiclesData[selectedRoom].map(vehicle => (
                                        <div key={vehicle.id} style={vehicleItemStyle}>
                                            <div style={{ display: 'flex', gap: '20px' }}>
                                                <span><strong>Loại xe:</strong> {vehicle.type}</span>
                                                <span><strong>Biển số:</strong> {vehicle.plate}</span>
                                            </div>
                                            <button style={btnDetailStyle}>Chi tiết</button>
                                        </div>
                                    ))
                                ) : (
                                    <p style={emptyTextStyle}>Phòng này chưa có phương tiện nào được đăng ký.</p>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div style={placeholderStyle}>
                            <p>Vui lòng chọn một số phòng ở bên trái để xem thông tin phương tiện...</p>
                        </div>
                    )}
                </div>
            </div>

            {/* CSS Scrollbar mượt mà */}
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.3); border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- HỆ THỐNG STYLES ---
const containerStyle = {
    flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column',
    backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
    backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)',
    padding: '20px'
};

const headerTitleStyle = { color: '#fff', fontSize: '20px', marginBottom: '20px', textShadow: '0 2px 4px rgba(0,0,0,0.3)' };

const contentWrapperStyle = { display: 'flex', flex: 1, gap: '20px', overflow: 'hidden' };

const leftSidebarStyle = {
    width: '320px', backgroundColor: 'rgba(255,255,255,0.15)', backdropFilter: 'blur(10px)',
    borderRadius: '25px', padding: '20px', overflowY: 'auto'
};

const roomGridStyle = { display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '10px' };

const roomButtonStyle = {
    padding: '10px 5px', border: 'none', borderRadius: '8px', fontWeight: 'bold',
    cursor: 'pointer', transition: '0.2s', fontSize: '13px'
};

const rightContentStyle = {
    flex: 1, backgroundColor: 'rgba(255,255,255,0.95)', borderRadius: '25px',
    padding: '30px', display: 'flex', flexDirection: 'column'
};

const infoCardStyle = { height: '100%', display: 'flex', flexDirection: 'column' };

const roomHeaderStyle = { fontSize: '32px', color: '#8b5e5e', margin: '0 0 10px 0', fontWeight: 'bold' };

const dividerStyle = { height: '2px', background: '#eee', marginBottom: '20px' };

const vehicleListContainer = { flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' };

const vehicleItemStyle = {
    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
    padding: '15px 20px', backgroundColor: '#f9f9f9', borderRadius: '15px', border: '1px solid #eee'
};

const btnDetailStyle = {
    padding: '5px 15px', borderRadius: '8px', border: '1px solid #8b5e5e',
    color: '#8b5e5e', background: 'none', cursor: 'pointer', fontSize: '12px'
};

const placeholderStyle = {
    flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
    color: '#999', fontStyle: 'italic', textAlign: 'center'
};

const emptyTextStyle = { color: '#999', textAlign: 'center', marginTop: '20px' };

export default QuanLyPhuongTien;
